head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF91300_REPORTRESULT";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.method

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91300_reportresult.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_5", fn: function(){ return ((dma_pageContext.get("method") ?? "")==='srchReport12'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "<![CDATA[" + String(dma_map.get("stdCd")) + "]]\u003e"; } },
        { childId: "__rb1", fn: function () { return "<![CDATA[" + String(dma_map.get("no1")) + "]]\u003e"; } },
        { childId: "__rb2", fn: function () { return "<![CDATA[" + String(dma_map.get("isuNm")) + "]]\u003e"; } },
        { childId: "__rb3", fn: function () { return "<![CDATA[" + String(dma_map.get("isuEngNm")) + "]]\u003e"; } },
        { childId: "__rb4", fn: function () { return "<![CDATA[" + String(dma_map.get("optExerPrcToFormat")) + "]]\u003e"; } },
        { childId: "__rb5", fn: function () { return "<![CDATA[" + String(dma_map.get("expDate")) + "]]\u003e"; } },
        { childId: "__rb6", fn: function () { return "<![CDATA[" + String(dma_map.get("futoptListTpNm")) + "]]\u003e"; } },
        { childId: "__rb7", fn: function () { return "<![CDATA[" + String(dma_map.get("activTpNm")) + "]]\u003e"; } },
        { childId: "__rb8", fn: function () { return "<![CDATA[" + String(dma_map.get("secuMktStkcertListDate")) + "]]\u003e"; } },
        { childId: "__rb9", fn: function () { return "<![CDATA[" + String(dma_map.get("secuMktStkcertDelistDate")) + "]]\u003e"; } },
        { childId: "__rb10", fn: function () { return "<![CDATA[" + String(dma_map.get("oldFutExchListDate")) + "]]\u003e"; } },
        { childId: "__rb11", fn: function () { return "<![CDATA[" + String(dma_map.get("oldFutExchDelistDate")) + "]]\u003e"; } },
        { childId: "__rb12", fn: function () { return "<![CDATA[" + String(dma_map.get("futoptUpclssNm")) + "]]\u003e"; } },
        { childId: "__rb13", fn: function () { return "<![CDATA[" + String(dma_map.get("fncUlyTpNm")) + "]]\u003e"; } },
        { childId: "__rb14", fn: function () { return "<![CDATA[" + String(dma_map.get("prodUlyTpNm")) + "]]\u003e"; } },
        { childId: "__rb15", fn: function () { return "<![CDATA[" + String(dma_map.get("elwSetlMethdNm")) + "]]\u003e"; } },
        { childId: "__rb16", fn: function () { return "<![CDATA[" + String(dma_map.get("stdYnNm")) + "]]\u003e"; } },
        { childId: "__rb17", fn: function () { return "<![CDATA[" + String(dma_map.get("fncProdFutTpNm")) + "]]\u003e"; } },
        { childId: "__rb18", fn: function () { return "<![CDATA[" + String(dma_map.get("callputTpNm")) + "]]\u003e"; } },
        { childId: "__rb19", fn: function () { return "<![CDATA[" + String(dma_map.get("exerTpNm")) + "]]\u003e"; } },
        { childId: "__rb20", fn: function () { return "<![CDATA[" + String(dma_map.get("refCdId")) + "]]\u003e"; } },
        { childId: "__rb21", fn: function () { return "<![CDATA[" + String(dma_map.get("cfiCd")) + "]]\u003e"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
